def make_palindrome(string: str) -> str:
    def is_palindrome(s: str) -> bool:
        return s == s[::-1]

    n = len(string)
    if n == 0:
        return ""

    # Find the longest palindromic suffix
    for i in range(n):
        if is_palindrome(string[i:]):
            longest_suffix_length = n - i
            break

    # Append the reverse of the prefix that is not part of the palindrome
    prefix = string[:n - longest_suffix_length]
    return string + prefix[::-1]

